		db.Say("", "\"A truck didn't arrive. {bind:truck}. The crew's on the list of people we look for.\"");
		db.Choice("how4", "\"And here?\"", "hub", "", "", "", "", "", "call:slot:0", "", "");
		db.Choice("back4", "\"Something else.\"", "hub", "", "", "", "", "", "", "", "");
		db.Conv("named.bastion.work", "named:bastion", "!hunted:bastion", "Ask how the shift's going.", 1, 0, "bastion");
		db.Node("start");
		db.Say("role:sentry & night", "\"Night shift. Four hours of looking at a road that looks back.\"");
		db.Say("role:sentry", "\"Quiet. Quiet is logged as quiet. Loud is logged as loud. I'm a very simple instrument.\"");
		db.Say("role:radio_operator", "\"Called Command at oh-six-hundred. Static. Logged the static. It's a very consistent static.\"");
		db.Say("role:mechanic", "\"Two vehicles. One runs. The other is a source of parts and comfort.\"");
		db.Say("role:medic & persona:3", "\"Three sick, one hurt, one pretending to be sick to get out of the latrine rota.\"");
		db.Say("role:medic", "\"Quiet in the aid post. Quiet's good. I'm not used to good.\"");
		db.Say("", "\"Same as yesterday.\"");
		db.Choice("what", "\"Anything that'd make it easier?\"", "ask", "", "", "", "", "", "", "", "");
