		db.Say("role:lab_assistant", "\"Labelling. Four hundred tubes. If one label is wrong, a week is wrong.\"");
		db.Say("role:guard & persona:2", "\"Standing. I stand very well. Eight hours, two doors, one of which doesn't lock.\"");
		db.Say("role:guard", "\"Watching the door. The door is the most important thing in the lab. Nobody believes me.\"");
		db.Say("role:technician", "\"The generator. It runs at seventy percent. Below sixty, the cultures die. I check it every hour.\"");
